function getLinuxIfaceConnectionName(interfaceName) {
  try {
    const output = execFileSync('nmcli', ['device', 'status'], { ...util.execOptsLinux, stdio: ['ignore', 'pipe', 'ignore'] }).toString();
    const result = util.grep(output, interfaceName);

    const resultFormat = result.replace(/\s+/g, ' ').trim();
    const connectionNameLines = resultFormat.split(' ').slice(3);
    const connectionName = connectionNameLines.join(' ');
    const connectionNameSanitized = util.sanitizeString(connectionName, false);

    return connectionNameSanitized !== '--' ? connectionNameSanitized : '';
  } catch {
    return '';
  }
}

function checkLinuxDCHPInterfaces(file) {
  let result = [];
  try {
    const cmd = `cat ${file} 2> /dev/null | grep 'iface\\|source'`;
    const lines = execSync(cmd, util.execOptsLinux).toString().split('\n');

    lines.forEach((line) => {
      const parts = line.replace(/\s+/g, ' ').trim().split(' ');
      if (parts.length >= 4) {
        if (line.toLowerCase().indexOf(' inet ') >= 0 && line.toLowerCase().indexOf('dhcp') >= 0) {
          result.push(parts[1]);
        }
      }
      if (line.toLowerCase().includes('source')) {
        const file = line.split(' ')[1];
        result = result.concat(checkLinuxDCHPInterfaces(file));

		return false
	}
}

// sameOrigin reports whether a request's browser-asserted provenance is
// same-origin, or absent entirely (a non-browser client). It rejects when
// Sec-Fetch-Site indicates a cross-origin initiator or when the Origin host
// differs from the request Host.
func sameOrigin(r *http.Request) bool {
	switch r.Header.Get("Sec-Fetch-Site") {
	case "", "same-origin", "none":
		// Same-origin, a direct user navigation, or a non-browser client (header
		// absent). Fall through to the Origin cross-check.
	default: // "cross-site", "same-site"
		return false
	}

	if origin := r.Header.Get("Origin"); origin != "" {
		if origin == "null" {
			return false // opaque/sandboxed cross-origin context
		}
		u, err := url.Parse(origin)
		if err != nil || !strings.EqualFold(reqHostname(u.Host), reqHostname(r.Host)) {
			return false
		}
	}
	return true
}

